/** @ignore this events must be defined on domNode (do not bubble) */
export const unbubbleEvents = {
    mouseleave: 1, mouseenter: 1, load: 1, unload: 1, scroll: 1, focus: 1, blur: 1, rowexit: 1, beforeunload: 1, stop: 1,
    dragdrop: 1, dragenter: 1, dragexit: 1, draggesture: 1, dragover: 1, contextmenu: 1, created: 2, removed: 2, sizechange: 2
};
const event_handlers = new WeakMap();
/**
 * handle dom mutations
 */
let mutObserver = null;
const observeMutation = (mutations, observer) => {
    const sendEvent = (node, code) => {
        //		console.log( "notify", node, code );
        const store = event_handlers.get(node);
        if (store && store[code]) {
            node.dispatchEvent(new Event(code, {}));
        }
    };
    const notify = (node, create) => {
        if (create) {
            sendEvent(node, "created");
        }
        for (let c = node.firstChild; c; c = c.nextSibling) {
            notify(c, create);
        }
        if (!create) {
            sendEvent(node, "removed");
        }
    };
    for (const mutation of mutations) {
        if (mutation.type == "childList") {
            if (mutation.addedNodes) {
                mutation.addedNodes.forEach(node => {
                    notify(node, true);
                });
            }
            if (mutation.removedNodes) {
                mutation.removedNodes.forEach(node => {
                    notify(node, false);
                });
            }
        }
    }
};
/**
 *
 */
let sizeObserver = null;
function observeSize(entries) {
    entries.forEach((entry) => {
        let dom = entry.target;
        if (dom.offsetParent !== null) {
            dom.dispatchEvent(new Event('resized'));
        }
    });
}
/**
 * Manually dispatches an event through the custom event system.
 * Simulates bubbling unless the event type is in the unbubbleEvents list.
 *
 * @param ev - The event to dispatch.
 */
export function dispatchEvent(ev) {
    let target = ev.target, noup = unbubbleEvents[ev.type] === 2;
    while (target) {
        const store = event_handlers.get(target);
        if (store) {
            const callback = store[ev.type];
            if (callback) {
                if (Array.isArray(callback)) {
                    callback.some(c => c(ev));
                }
                else {
                    callback(ev);
                }
                if (ev.defaultPrevented || noup) {
                    break;
                }
            }
        }
        target = target.parentNode;
        // no need to go above
        if (target == document) {
            break;
        }
    }
}
/**
 * Registers an event handler for a specific node.
 * Automatically initializes MutationObserver or ResizeObserver if special events
 * ('created', 'removed', 'resized') are requested.
 *
 * @param node - The target DOM node.
 * @param name - The name of the event to listen for.
 * @param handler - The function to call when the event occurs.
 * @param prepend - Whether to prepend the handler to the list (default: false).
 */
export function addEvent(node, name, handler, prepend = false) {
    if (name == "removed" || name == "created") {
        if (!mutObserver) {
            mutObserver = new MutationObserver(observeMutation);
            mutObserver.observe(document.body, { childList: true, subtree: true });
        }
    }
    else if (name == "resized") {
        if (!sizeObserver) {
            sizeObserver = new ResizeObserver(observeSize);
        }
        sizeObserver.observe(node);
    }
    let store = event_handlers.get(node);
    if (!store) {
        store = {};
        event_handlers.set(node, store);
    }
    if (!store[name]) {
        store[name] = handler;
        node.addEventListener(name, dispatchEvent);
    }
    else {
        const entry = store[name];
        if (Array.isArray(entry)) {
            entry.push(handler);
        }
        else {
            store[name] = [entry, handler];
        }
    }
}
